using Microsoft.EntityFrameworkCore;
class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(entity =>
        {
            entity.ToContainer("Products");

            // EF Core 9 renamed the default discriminator from "Discriminator" to "$type".
            // Existing 500K documents use "Discriminator", and direct SQL queries reference
            // c.Discriminator — keep the old property name for data compatibility.
            entity.HasDiscriminator<string>("Discriminator");

            // EF Core 9 changed the id format from "EntityType|KeyValue" (e.g. "Product|123")
            // to just the key value ("123"). Existing documents use the compound format —
            // keep it so FindAsync and point-reads still work against existing data.
            entity.HasRootDiscriminatorInJsonId(true);
        });

        // EF Core 9 Cosmos provider: HasIndex() now throws InvalidOperationException at
        // startup instead of being silently ignored. Cosmos DB indexing is managed via the
        // container's indexing policy (Azure Portal / Bicep / Terraform), not EF Core.
        // REMOVED: modelBuilder.Entity<Product>().HasIndex(p => p.Sku);
    }
}
class Product { public int Id { get; set; } public string Sku { get; set; } }

