class CosmosQuery
{
    // EF Core 9 Cosmos provider: synchronous I/O (ToList, SaveChanges, etc.) now throws.
    // All queries must use async equivalents (ToListAsync, SaveChangesAsync, etc.).
    async Task FindProducts(ProductContext ctx)
    {
        // Direct Cosmos SQL — kept referencing c.Discriminator (not c["$type"]) because
        // we configured HasDiscriminator<string>("Discriminator") in the model to preserve
        // compatibility with existing documents.
        var sql = "SELECT * FROM c WHERE c.Discriminator = 'Product' AND c.Sku = @sku";

        var products = await ctx.Products.Where(p => p.Sku == "ABC").ToListAsync();
    }
}

